// HU-13 T01 - Sondas de los dos servicios publicos. No llevan credenciales:
// /healthz de n8n y /health de la API de riesgo son endpoints abiertos.
//
// Las URLs estan aqui arriba, juntas, para cambiarlas en un solo sitio.
const URL_N8N = 'https://urbanpulse-n8n.xq33kajky1yy6.us-east-1.cs.amazonlightsail.com';
const URL_API_RIESGO = 'https://urbanpulse-api.xq33kajky1yy6.us-east-1.cs.amazonlightsail.com';

// El contrato promete responder en menos de 3 s. Con 2 s por sonda, un
// servicio caido degrada la respuesta en vez de colgar el webhook.
const TIMEOUT_MS = 2000;

const sondar = async (url) => {
  const inicio = Date.now();
  try {
    const cuerpo = await this.helpers.httpRequest({
      method: 'GET', url, timeout: TIMEOUT_MS, json: true,
    });
    return { estado: 'ONLINE', latencia_ms: Date.now() - inicio, cuerpo };
  } catch (e) {
    return {
      estado: 'OFFLINE',
      latencia_ms: Date.now() - inicio,
      error: String((e && e.message) || e).slice(0, 200),
    };
  }
};

const n8n = await sondar(URL_N8N + '/healthz');
const api = await sondar(URL_API_RIESGO + '/health');

// t_db se toma justo antes del nodo de Postgres, que es el siguiente y va
// directo a "Armar estado de la plataforma": asi la latencia de Neon es la de
// esa consulta y nada mas. Las consultas a Jira van ANTES de este nodo; antes
// iban despues de Neon y su tiempo se sumaba a la latencia de la base.
return [{ json: { n8n, api, t_db: Date.now() } }];

// HU-13 T01 - Arma la respuesta del contrato
// (docs/PLATFORM_HEALTH_WEBHOOK_CONTRACT.md) con lo que devolvieron las
// sondas, Neon y Jira. Toda la logica de "que estado reportar" vive aqui, y
// por eso este nodo es el que tiene pruebas.
const PORTAL_JIRA = 'https://urbanpulse-ti.atlassian.net';
const DIAS_MONITOREO_VIGENTE = 7;
const VERSION_CONTRATO = '1.2.0';

const leer = (nodo) => {
  try { return $(nodo).first().json || {}; } catch (e) { return {}; }
};

const sondas = leer('Sondar n8n y la API de riesgo');
const neon = leer('Neon: ping y ultimo monitoreo');
const jiraAbiertos = leer('Jira: tickets abiertos');
const jiraDelMes = leer('Jira: tickets del mes con SLA');
const jiraVencidos = leer('Jira: tickets con SLA vencido');
const github = leer('GitHub: ultimo despliegue');

// --- Servicios ------------------------------------------------------------
// Neon no se da por bueno copiando el estado de otro servicio: o la consulta
// devolvio ok = 1, o esta OFFLINE.
const sondaN8n = sondas.n8n || {};
const sondaApi = sondas.api || {};
const neonEnLinea = !neon.error && Number(neon.ok) === 1;

const servicios = [
  {
    nombre: 'n8n_engine',
    estado: sondaN8n.estado || 'DESCONOCIDO',
    latencia_ms: sondaN8n.latencia_ms === undefined ? null : sondaN8n.latencia_ms,
  },
  {
    nombre: 'fastapi_mlops',
    estado: sondaApi.estado || 'DESCONOCIDO',
    latencia_ms: sondaApi.latencia_ms === undefined ? null : sondaApi.latencia_ms,
  },
  {
    nombre: 'neon_postgres',
    estado: neonEnLinea ? 'ONLINE' : 'OFFLINE',
    latencia_ms: typeof sondas.t_db === 'number' ? Date.now() - sondas.t_db : null,
  },
];

const enLinea = servicios.filter((s) => s.estado === 'ONLINE').length;
const estadoPlataforma = enLinea === servicios.length
  ? 'OPERATIVO'
  : (enLinea === 0 ? 'CAIDO' : 'DEGRADADO');

// --- Monitoreo del modelo -------------------------------------------------
// La version que sirve la API manda sobre lo demas: es el modelo que de
// verdad esta respondiendo /predict. El F1 y la deriva salen del ultimo
// evento que publico ml-monitoring.yml (HT-49 T03) y que el enrutador de
// HT-51 dejo en la tabla eventos.
const tag = String((sondaApi.cuerpo || {}).model_version || '');
const modeloApi = tag.includes('@') ? tag.split('@')[0] : (tag || null);
const versionApi = tag.includes('@') ? tag.split('@')[1] : null;

const datosEvento = (neon.datos && typeof neon.datos === 'object') ? neon.datos : null;
const fechaEvento = neon.fecha ? new Date(neon.fecha) : null;
const fechaValida = fechaEvento && !isNaN(fechaEvento.getTime());
const vigente = fechaValida
  && (Date.now() - fechaEvento.getTime()) <= DIAS_MONITOREO_VIGENTE * 86400000;

const monitoreoModelo = {
  modelo: modeloApi || (datosEvento ? datosEvento.modelo : null),
  version: versionApi || (datosEvento && datosEvento.version !== undefined
    && datosEvento.version !== null ? String(datosEvento.version) : null),
  // null, no false: sin evento no es que no haya deriva, es que no se sabe.
  f1_score: datosEvento && datosEvento.f1_real !== undefined && datosEvento.f1_real !== null
    ? Number(datosEvento.f1_real) : null,
  deriva_detectada: neon.tipo ? neon.tipo === 'modelo.deriva_detectada' : null,
  ultimo_monitoreo: fechaValida ? fechaEvento.toISOString() : null,
  monitoreo_vigente: Boolean(vigente),
  // Por que el ultimo monitoreo no trae F1 o PSI (por ejemplo, porque aun no
  // hay predicciones suficientes). null si no hay nada que aclarar.
  observacion: datosEvento && datosEvento.motivo ? String(datosEvento.motivo) : null,
};

// --- Service Desk ---------------------------------------------------------
// POST /rest/api/3/search/approximate-count devuelve { count }. El endpoint
// anterior (/rest/api/3/search, que devolvia { total }) Atlassian lo retiro de
// Jira Cloud. Si una consulta falla, su dato queda en null en vez de inventarse.
const contadorDe = (r) => {
  if (!r || r.error) return null;
  if (typeof r.count === 'number') return r.count;
  return typeof r.total === 'number' ? r.total : null;
};
const abiertos = contadorDe(jiraAbiertos);

// Cumplimiento de SLA DEL MES (criterio 3 de HU-13): de los tickets creados
// este mes con el SLA "Tiempo de primera respuesta", que porcentaje no lo
// vencio. Es el SLA que el portal UPTI aplica a todas las solicitudes desde que
// se crean; el otro ("Time to close after resolution") solo corre despues de
// resolver, asi que no sirve para medir la atencion.
const delMes = contadorDe(jiraDelMes);
const vencidosMes = contadorDe(jiraVencidos);
let cumplimiento = null;
if (delMes !== null && vencidosMes !== null) {
  cumplimiento = delMes === 0
    ? 100
    : Math.round((Math.max(delMes - vencidosMes, 0) / delMes) * 1000) / 10;
}

// --- Ultimo despliegue (criterio 2 de HU-13) ------------------------------
// El mas reciente entre los workflows de despliegue que encontro GitHub.
const recientes = (Array.isArray(github.despliegues) ? github.despliegues : [])
  .filter((d) => d && d.fecha && !isNaN(new Date(d.fecha).getTime()))
  .sort((a, b) => new Date(b.fecha) - new Date(a.fecha));
const ultimoDespliegue = recientes.length
  ? {
    fecha: new Date(recientes[0].fecha).toISOString(),
    commit: recientes[0].commit || null,
    workflow: recientes[0].workflow || null,
    url: recientes[0].url || null,
  }
  : null;

return [{
  json: {
    estado_plataforma: estadoPlataforma,
    timestamp: new Date().toISOString(),
    version: VERSION_CONTRATO,
    servicios,
    ultimo_despliegue: ultimoDespliegue,
    monitoreo_modelo: monitoreoModelo,
    service_desk_jira: {
      tickets_abiertos: abiertos,
      cumplimiento_sla_porcentaje: cumplimiento,
      portal_url: PORTAL_JIRA,
    },
  },
}];

// HU-13 T01 - Ultimo despliegue a produccion (criterio 2 de HU-13).
// La fuente es GitHub Actions: la ultima ejecucion exitosa en main de cada
// workflow de despliegue (n8n y la API de riesgo). El repositorio es publico,
// asi que no lleva credenciales; sin token GitHub admite 60 consultas por hora
// desde la misma IP, de sobra para la pantalla de Ajustes. Si GitHub no
// responde, el dato sale en null en "Armar estado", nunca inventado.
const REPO = 'SergioAscurraPerez/equipo3-urbanpulse';
const WORKFLOWS = ['deploy-lightsail-n8n.yml', 'deploy-api-inferencia.yml'];
const TIMEOUT_MS = 2000;

const despliegues = [];
const errores = [];
for (const archivo of WORKFLOWS) {
  try {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.github.com/repos/${REPO}/actions/workflows/${archivo}/runs`,
      qs: { branch: 'main', status: 'success', per_page: 1 },
      headers: {
        'User-Agent': 'urbanpulse-estado-plataforma',
        Accept: 'application/vnd.github+json',
      },
      timeout: TIMEOUT_MS,
      json: true,
    });
    const run = ((r && r.workflow_runs) || [])[0];
    if (run) {
      despliegues.push({
        workflow: run.name,
        fecha: run.updated_at,
        commit: String(run.head_sha || '').slice(0, 7),
        url: run.html_url,
      });
    }
  } catch (e) {
    errores.push(`${archivo}: ${String((e && e.message) || e).slice(0, 120)}`);
  }
}

return [{ json: { despliegues, errores } }];
